//! The generated files: the requirement index, the open item index and the traceability
//! matrix (REQ-052, REQ-053).

use std::collections::BTreeMap;
use std::fs;
use std::io;
use std::path::Path;

use super::{
    Baseline, MATRIX, OPEN_ITEM_INDEX, REQUIREMENT_INDEX, Requirement, Spec, SpecError,
    Verification, Violation, check, load,
};

/// The command that writes the generated files.
const COMMAND: &str = "cargo run -p atari-harness --bin spec-index";

/// Escapes `|` for a markdown table cell.
fn cell(text: &str) -> String {
    text.replace('|', "\\|")
}

/// The text of `docs/spec/requirements/INDEX.md`.
#[must_use]
pub fn requirement_index(spec: &Spec) -> String {
    let mut lines = vec![
        "# Requirement index".to_owned(),
        String::new(),
        format!("Generated by `{COMMAND}`. Do not edit."),
        String::new(),
        "| ID | Title | Status | Priority | Area | Verification |".to_owned(),
        "| --- | --- | --- | --- | --- | --- |".to_owned(),
    ];
    for r in &spec.requirements {
        lines.push(format!(
            "| [REQ-{id:03}](REQ-{id:03}.md) | {} | {} | {} | {} | {} |",
            cell(&r.title),
            r.status.as_str(),
            r.priority.as_str(),
            r.area,
            r.verification.as_str(),
            id = r.id,
        ));
    }
    lines.push(String::new());
    lines.join("\n")
}

/// The text of `docs/spec/open-items/README.md`.
#[must_use]
pub fn open_item_index(spec: &Spec) -> String {
    let mut lines = vec![
        "# Open items".to_owned(),
        String::new(),
        "An open item is a question that the specification cannot answer without a decision. \
         Each"
            .to_owned(),
        "item has its own file: `OI-NNN.md`. When a decision is made, write it in the \
         `Decision`"
            .to_owned(),
        "section, set `status: decided` in the frontmatter, and change the affected \
         requirements."
            .to_owned(),
        String::new(),
        format!("Generated by `{COMMAND}`. Do not edit."),
        String::new(),
        "| Item | Title | Area | Status |".to_owned(),
        "| --- | --- | --- | --- |".to_owned(),
    ];
    for item in &spec.open_items {
        lines.push(format!(
            "| [OI-{id:03}](OI-{id:03}.md) | {} | {} | {} |",
            cell(&item.title),
            item.area.join(", "),
            item.status.as_str(),
            id = item.id,
        ));
    }
    lines.push(String::new());
    lines.join("\n")
}

/// The state of a requirement in the matrix (REQ-027).
fn state(spec: &Spec, r: &Requirement) -> &'static str {
    let (running, ignored) =
        spec.tests_of(r.id).fold(
            (0, 0),
            |(a, i), t| if t.ignored { (a, i + 1) } else { (a + 1, i) },
        );
    match (running, ignored) {
        (0, 0) if r.verification != Verification::Test => "not a test requirement",
        (0, 0) => "missing",
        (0, _) => "pending",
        _ => "tested",
    }
}

/// The tests of a requirement for the matrix.
fn tests(spec: &Spec, r: &Requirement) -> String {
    spec.tests_of(r.id)
        .map(|t| {
            let ignored = if t.ignored { " (ignored)" } else { "" };
            format!("{} `{}`{ignored}", t.file.display(), t.function)
        })
        .collect::<Vec<_>>()
        .join("<br>")
}

/// The evidence of a requirement for the matrix.
fn evidence(spec: &Spec, r: &Requirement) -> String {
    spec.evidence
        .iter()
        .filter(|e| e.requirement == Some(r.id))
        .map(|e| format!("{} ({})", e.path.display(), e.result.as_str()))
        .collect::<Vec<_>>()
        .join("<br>")
}

/// The traceability matrix (REQ-027, REQ-050, REQ-052): one row for each requirement that
/// is not withdrawn, the section "Not in a slice", the counts and the violations that the
/// baseline does not list.
#[must_use]
pub fn matrix(spec: &Spec, violations: &[Violation], baseline: &Baseline) -> String {
    let mut lines = vec![
        "# Traceability matrix".to_owned(),
        String::new(),
        format!("Generated by `{COMMAND}` and by `crates/harness/tests/traceability.rs`."),
        String::new(),
        "| Requirement | Verification | Slice and package | State | Tests | Evidence |".to_owned(),
        "| --- | --- | --- | --- | --- | --- |".to_owned(),
    ];
    let mut counts: BTreeMap<&str, usize> = BTreeMap::new();
    let mut unplanned = Vec::new();
    for r in spec.requirements.iter().filter(|r| r.active()) {
        let state = state(spec, r);
        *counts.entry(state).or_default() += 1;
        let planned = spec.planned(r.id).map_or_else(
            || {
                unplanned.push(format!("- REQ-{:03}: {}", r.id, r.title));
                "not in a slice".to_owned()
            },
            |(slice, package)| format!("SLICE-{:02} {}", slice.id, package.id),
        );
        lines.push(format!(
            "| REQ-{:03} | {} | {planned} | {state} | {} | {} |",
            r.id,
            r.verification.as_str(),
            tests(spec, r),
            evidence(spec, r),
        ));
    }
    lines.extend([String::new(), "## Not in a slice".to_owned(), String::new()]);
    if unplanned.is_empty() {
        lines.push("None.".to_owned());
    }
    lines.extend(unplanned);
    let new = baseline.filter(violations);
    let summary: Vec<String> = counts.iter().map(|(s, n)| format!("{s}: {n}")).collect();
    lines.extend([
        String::new(),
        "## Counts".to_owned(),
        String::new(),
        format!(
            "Counts: {}. Violations: {} new, {} in the baseline.",
            summary.join(", "),
            new.len(),
            violations.len() - new.len()
        ),
        String::new(),
    ]);
    lines.extend(violation_tables(violations, &new));
    lines.push(String::new());
    lines.join("\n")
}

/// The table of new violations and the baseline count of each rule.
fn violation_tables(all: &[Violation], new: &[Violation]) -> Vec<String> {
    let mut lines = vec!["## Violations".to_owned(), String::new()];
    if new.is_empty() {
        lines.push("No new violations.".to_owned());
    } else {
        lines.push("| Rule | File | Line | Message |".to_owned());
        lines.push("| --- | --- | --- | --- |".to_owned());
        for v in new {
            let line = v.line.map_or_else(String::new, |l| l.to_string());
            lines.push(format!(
                "| REQ-{:03} | {} | {line} | {} |",
                v.rule,
                v.file.display(),
                cell(&v.message)
            ));
        }
    }
    let mut known: BTreeMap<u16, usize> = BTreeMap::new();
    for v in all.iter().filter(|v| !new.contains(v)) {
        *known.entry(v.rule).or_default() += 1;
    }
    lines.extend([
        String::new(),
        "### Baseline violations by rule".to_owned(),
        String::new(),
        "| Rule | Violations |".to_owned(),
        "| --- | --- |".to_owned(),
    ]);
    lines.extend(
        known
            .iter()
            .map(|(rule, n)| format!("| REQ-{rule:03} | {n} |")),
    );
    lines
}

/// Writes a file below `root`, and creates its directory.
fn write(root: &Path, rel: &str, text: &str) -> Result<(), SpecError> {
    let path = root.join(rel);
    let io = |error: io::Error| SpecError::Io {
        path: path.clone(),
        message: error.to_string(),
    };
    if let Some(dir) = path.parent() {
        fs::create_dir_all(dir).map_err(io)?;
    }
    fs::write(&path, text).map_err(io)
}

/// Writes `docs/spec/requirements/INDEX.md`, `docs/spec/open-items/README.md` and
/// `target/traceability.md` below `root`. Gives the counts line of the matrix.
///
/// # Errors
///
/// A [`SpecError`] if the repository cannot be read or a file cannot be written.
pub fn generate(root: &Path) -> Result<String, SpecError> {
    let spec = load(root)?;
    write(root, REQUIREMENT_INDEX, &requirement_index(&spec))?;
    write(root, OPEN_ITEM_INDEX, &open_item_index(&spec))?;
    let violations = check(&spec, root);
    let report = matrix(&spec, &violations, &Baseline::read(root)?);
    write(root, MATRIX, &report)?;
    Ok(report
        .lines()
        .find(|l| l.starts_with("Counts: "))
        .unwrap_or_default()
        .to_owned())
}
